    /**
     * 控制动画画面从在某一帧或某个时刻开始播放
     * @param value 帧号(>=0)或时刻(ms)
     * @param isFrame true按帧控制, false按时间控制, 缺省默认false
     * @param name 被指定的动画名, 可缺省默认为空
     * @since 8
     * @design
     */
    goToAndPlay(value: number, isFrame?: boolean, name?: string): void;

    /**
     * 限定动画资源播放时的整体帧范围
     * @param init 起始帧号
     * @param end 结束帧号
     * @since 8
     * @design
